const DEVELOPMENT_GATE = false;
if (!DEVELOPMENT_GATE) throw new Error('GA4_DEVELOPMENT_GATE_CLOSED');
return $input.all();

const parts = Object.fromEntries(new Intl.DateTimeFormat('en-GB',{ timeZone:'Europe/London', year:'numeric', month:'2-digit', day:'2-digit' }).formatToParts(new Date()).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));
const today = `${parts.year}-${parts.month}-${parts.day}`;
const endMs = Date.parse(today + 'T00:00:00Z');
const start = new Date(endMs - 3 * 86400000).toISOString().slice(0,10);
return [{ json:{ propertyId:298253309, start, end:today, today, runStartedAt:new Date().toISOString(), scheduleTimezone:'Europe/London', overlapDays:3 } }];

const window = $('Current GA4 Window').first().json;
const runAt = window.runStartedAt || new Date().toISOString();
const isoDay = value => { const s = String(value || ''); if (!/^\d{8}$/.test(s)) throw new Error('GA4_DATE_INVALID:' + s); return s.slice(0,4) + '-' + s.slice(4,6) + '-' + s.slice(6,8); };
const num = value => { const n = Number(value); return Number.isFinite(n) ? n : 0; };
const metric = row => ({ sessions:Math.max(0, Math.round(num(row.sessions))), engaged_sessions:Math.max(0, Math.round(num(row.engagedSessions))), event_count:Math.max(0, Math.round(num(row.eventCount))), add_to_carts:Math.max(0, Math.round(num(row.addToCarts))), checkouts:Math.max(0, Math.round(num(row.checkouts))), ecommerce_purchases:Math.max(0, Math.round(num(row.ecommercePurchases))), purchase_revenue:num(row.purchaseRevenue), is_provisional:isoDay(row.date) === window.today, source_updated_at:runAt });
const rows = $input.all().map(item => { const row = item.json; return { property_id:298253309, day:isoDay(row.date), currency_code:'GBP', ...metric(row) }; });
return [{ json:{ ...window, dimensionType:'daily', rows } }];

